/* ---------- voxel kit: the whole room is built from blocks + pixel textures, so the character belongs in it ---------- */
function pcanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');
  return {c,g,w,h,px(x,y,col){g.fillStyle=col;g.fillRect(x,y,1,1)},rect(x,y,ww,hh,col){g.fillStyle=col;g.fillRect(x,y,ww,hh)}}}
function ptex(p,rx=1,ry=1){const t=new THREE.CanvasTexture(p.c);t.magFilter=THREE.NearestFilter;t.encoding=THREE.sRGBEncoding;
  if(rx!==1||ry!==1){t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rx,ry)}return t}
function pscreen(w,h){const p=pcanvas(w,h);p.t=ptex(p);p.t.minFilter=THREE.LinearFilter;p.t.generateMipmaps=false;return p}
let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;
function tone(hex,a){const n=parseInt(hex.slice(1),16);const f=v=>Math.max(0,Math.min(255,Math.round(v*(1+a))));
  return '#'+((1<<24)|(f(n>>16)<<16)|(f(n>>8&255)<<8)|f(n&255)).toString(16).slice(1)}
function noise(p,base,amt){for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++)p.px(x,y,tone(base,(rnd()-.5)*amt))}
const noisy=(p,base,amt)=>{noise(p,base,amt);return p};
function tile(base,amt,seam){const p=noisy(pcanvas(16,16),base,amt);
  if(seam)for(let i=0;i<16;i++){p.px(i,15,tone(base,-.3));p.px(15,i,tone(base,-.3));p.px(i,0,tone(base,.1));p.px(0,i,tone(base,.1))}return p}
function planks(){const p=pcanvas(16,16),b='#2a2420';
  for(let y=0;y<16;y++)for(let x=0;x<16;x++)p.px(x,y,tone(b,(rnd()-.5)*.18+((y>>2)%2?.05:-.03)));
  for(let y=0;y<16;y+=4)for(let x=0;x<16;x++)p.px(x,y,tone(b,-.38));
  [[5,1],[12,5],[3,9],[10,13]].forEach(([x,y])=>{for(let k=0;k<3;k++)p.px(x,y+k,tone(b,-.38))});return p}
const vmat=(map,o)=>new THREE.MeshStandardMaterial(Object.assign({map,roughness:.85,metalness:0},o||{}));
const cmat=(col,o)=>new THREE.MeshStandardMaterial(Object.assign({color:col,roughness:.8,metalness:0},o||{}));
const blk=(w,h,d,m,x,y,z,parent,shadow=true)=>mesh(box(w,h,d),m,x,y,z,parent,shadow);
function voxels(list,s,parent,o={}){const im=new THREE.InstancedMesh(new THREE.BoxGeometry(s,s,s),new THREE.MeshStandardMaterial({roughness:o.rough??.75,metalness:o.metal??0}),list.length);
  const M=new THREE.Matrix4(),c=new THREE.Color();list.forEach((v,i)=>{M.makeTranslation(v[0]*s,v[1]*s+s/2,v[2]*s);im.setMatrixAt(i,M);im.setColorAt(i,c.set(v[3]))});
  im.castShadow=im.receiveShadow=true;parent.add(im);return im}
/* a tiny 3x5 pixel font for screens and labels */
const FONT={A:'010101111101101',B:'110101110101110',C:'011100100100011',D:'110101101101110',E:'111100110100111',F:'111100110100100',G:'011100101101011',
  H:'101101111101101',I:'111010010010111',J:'001001001101010',K:'101101110101101',L:'100100100100111',M:'101111111101101',N:'110101101101101',
  O:'010101101101010',P:'110101110100100',Q:'010101101110011',R:'110101110101101',S:'011100010001110',T:'111010010010010',U:'101101101101111',
  V:'101101101101010',W:'101101111111101',X:'101101010101101',Y:'101101010010010',Z:'111001010100111',
  0:'111101101101111',1:'010110010010111',2:'110001010100111',3:'110001010001110',4:'101101111001001',5:'111100110001110',
  6:'011100110101010',7:'111001010010010',8:'010101010101010',9:'010101011001110',
  '.':'000000000000010','-':'000000111000000',':':'000010000010000',';':'000010000010100','_':'000000000000111','=':'000111000111000',
  '/':'001001010100100','%':'101001010100101','+':'000010111010000','(':'010100100100010',')':'010001001001010',',':'000000000010100',
  '·':'000000010000000','!':'010010010000010','?':'110001010000010',"'":'010010000000000'};
function ptext(p,str,x,y,col,sc=1,center=false){str=String(str).toUpperCase();if(center)x=Math.round(x-(str.length*4*sc-sc)/2);
  for(const ch of str){const gl=FONT[ch];if(gl)for(let i=0;i<15;i++)if(gl[i]==='1')p.rect(x+(i%3)*sc,y+Math.floor(i/3)*sc,sc,sc,col);x+=4*sc}}

/* room: dark block walls, dark plank floor */
