blk(4.4,.16,1.5,woodM,0,1.5,-3.9,desk);
[[-2.05,-3.3],[2.05,-3.3],[-2.05,-4.5],[2.05,-4.5]].forEach(p=>blk(.16,1.42,.16,cmat(0x15181c,{metalness:.4,roughness:.5}),p[0],.71,p[1],desk));
blk(4,.7,.06,cmat(0x1a1e23),0,1.05,-4.55,desk);

/* monitors with live pixel screens */
const mon1=pscreen(128,80),mon2=pscreen(128,80);
