for(let i=0;i<5;i++){const a=i/5*Math.PI*2;const l=blk(.08,.06,.5,cmat(0x15181c),Math.sin(a)*.25,.1,Math.cos(a)*.25,rig);l.rotation.y=a;
  blk(.1,.1,.1,cmat(0x0e1013),Math.sin(a)*.48,.05,Math.cos(a)*.48,rig)}
