/* ---------- the character: a voxel Ashwini (beard, mint blazer, white shirt, lapel mic) ---------- */
const C={skin:'#b27b56',skinD:'#a06a47',hair:'#16100d',hairL:'#2a1f19',beard:'#1a1310',beardL:'#2a2019',brow:'#140e0b',eyeW:'#efe9e1',iris:'#3b2214',pupil:'#120a06',
  mouth:'#4a1f18',lip:'#8a4a36',teeth:'#f3efe6',nose:'#94603f',ear:'#a16b4a',blz:'#8cbca3',lapel:'#6c9682',shirt:'#ecefea',btn:'#55705f',pants:'#262d40',shoe:'#2a1d16',sole:'#121212'};
const partMat=p=>vmat(ptex(p),{roughness:.85});
const tbox=(w,h,d,faces,x,y,z,parent)=>mesh(box(w,h,d),faces.map(partMat),x,y,z,parent);
const six=f=>[f(),f(),f(),f(),f(),f()];
const ch=new THREE.Group();rig.add(ch);
/* legs: thigh forward on the seat, shin down, shoe */
const legJoints=[];
[-1,1].forEach(s=>{const hip=new THREE.Group();hip.position.set(s*.19,1.15,-.1);ch.add(hip);
  const P=()=>noisy(pcanvas(8,8),C.pants,.12);
  tbox(.36,.34,.8,six(P),0,0,.36,hip);
  const knee=new THREE.Group();knee.position.set(0,0,.6);hip.add(knee);
  const shin=()=>{const p=noisy(pcanvas(8,24),C.pants,.12);for(let x=0;x<8;x++)p.px(x,23,tone(C.pants,-.3));return p};
  tbox(.34,1.12,.34,[shin(),shin(),P(),P(),shin(),shin()],0,-.39,0,knee);
  const sh=()=>{const p=noisy(pcanvas(8,4),C.shoe,.15);for(let x=0;x<8;x++)p.px(x,3,C.sole);return p};
  tbox(.38,.18,.52,[sh(),sh(),noisy(pcanvas(8,8),C.shoe,.15),noisy(pcanvas(8,8),C.sole,.1),sh(),sh()],0,-1.04,.07,knee);
  legJoints.push({hip,knee})});
/* torso: mint blazer over a white shirt */
const spine=new THREE.Group();spine.position.set(0,1.02,-.05);ch.add(spine);
const blz=(w,h)=>noisy(pcanvas(w,h),C.blz,.1);
const torsoFront=(()=>{const p=blz(16,20),L=C.lapel,S=C.shirt,K=C.skin;
  for(let y=0;y<=4;y++){p.px(6,y,S);p.px(9,y,S)}for(let y=3;y<=8;y++){p.px(7,y,S);p.px(8,y,S)}
  for(let y=0;y<=2;y++){p.px(7,y,K);p.px(8,y,K)}p.px(5,0,S);p.px(10,0,S);
  for(let y=1;y<=4;y++){p.px(5,y,L);p.px(10,y,L)}for(let y=5;y<=8;y++){p.px(6,y,L);p.px(9,y,L)}
  for(let y=9;y<20;y++)p.px(7,y,tone(C.blz,-.18));p.px(8,11,C.btn);p.px(8,15,C.btn);
  for(let x=2;x<=4;x++)p.px(x,14,L);for(let x=11;x<=13;x++){p.px(x,14,L);p.px(x,6,L)}p.px(11,4,'#0d0d0d');
  for(let x=0;x<16;x++)p.px(x,19,tone(C.blz,-.2));return p})();
const torsoSide=()=>{const p=blz(9,20);for(let x=0;x<9;x++)p.px(x,19,tone(C.blz,-.2));return p};
const torsoBack=(()=>{const p=blz(16,20);for(let y=6;y<20;y++)p.px(7,y,tone(C.blz,-.15));for(let x=0;x<16;x++)p.px(x,19,tone(C.blz,-.2));return p})();
const torsoTop=(()=>{const p=blz(16,9);for(let y=6;y<9;y++)for(let x=6;x<10;x++)p.px(x,y,C.shirt);return p})();
tbox(.78,.94,.44,[torsoSide(),torsoSide(),torsoTop,noisy(pcanvas(16,9),C.pants,.1),torsoFront,torsoBack],0,.47,0,spine);
/* neck + head */
const neck=new THREE.Group();neck.position.set(0,.94,0);spine.add(neck);
tbox(.3,.08,.3,six(()=>noisy(pcanvas(4,2),C.skin,.06)),0,.03,0,neck);
const head=new THREE.Group();head.position.set(0,.05,0);neck.add(head);
function headSide(frontLeft){const p=noisy(pcanvas(16,16),C.skin,.06),X=d=>frontLeft?d:15-d;   // a natural profile: cheek, ear, jaw beard
  for(let y=0;y<4;y++)for(let d=0;d<16;d++)p.px(X(d),y,C.hair);
  for(let y=4;y<12;y++)for(let d=11;d<16;d++)p.px(X(d),y,C.hair);
  p.px(X(9),4,C.hair);p.px(X(10),4,C.hair);
  for(let y=5;y<10;y++){p.px(X(0),y,C.beard);p.px(X(9),y,C.skinD);p.px(X(10),y,C.skinD)}
  for(let y=10;y<16;y++)for(let d=0;d<10;d++)p.px(X(d),y,tone(C.beard,(rnd()-.5)*.1));
  [[2,1],[11,2],[13,6]].forEach(([d,y])=>p.px(X(d),y,C.hairL));[[3,12],[6,14],[1,15]].forEach(([d,y])=>p.px(X(d),y,C.beardL));return p}
