  [[3,4],[10,11]].forEach(([x0,cx])=>{
    if(st.eyes==='closed'){for(let x=x0;x<x0+3;x++)p.px(x,7,C.iris)}
    else if(st.eyes==='happy'){p.px(cx,6,C.iris);p.px(x0,7,C.iris);p.px(x0+2,7,C.iris)}
    else{for(let y=6;y<=7;y++)for(let x=x0;x<x0+3;x++)p.px(x,y,C.eyeW);const ix=cx+st.ix;
      if(st.eyes==='down')p.px(ix,7,C.pupil);else{p.px(ix,6,C.pupil);p.px(ix,7,C.iris)}}});
  p.px(7,8,C.nose);p.px(8,8,C.nose);p.px(7,9,tone(C.nose,-.15));p.px(8,9,tone(C.nose,-.15));
  [0,1,14,15].forEach(x=>p.px(x,9,B));for(let x=0;x<3;x++)p.px(x,10,B);for(let x=13;x<16;x++)p.px(x,10,B);for(let x=4;x<=11;x++)p.px(x,10,B);
  for(let x=0;x<16;x++)for(let y=11;y<16;y++)p.px(x,y,B);[[2,13],[7,14],[11,13],[4,15],[13,14],[9,15],[1,12]].forEach(([x,y])=>p.px(x,y,C.beardL));
  const m=st.mouth;
