class Spring{constructor(v,k,d){this.x=v;this.v=0;this.t=v;this.k=k;this.d=d}
  step(dt){const a=this.k*(this.t-this.x)-this.d*this.v;this.v+=a*dt;this.x+=this.v*dt;return this.x}}
